class Solution:
    def isSubstringPresent(self, s: str) -> bool:
        pairs = {s[i:i+2] for i in range(len(s) - 1)}
        return any(s[i:i+2][::-1] in pairs for i in range(len(s) - 1))

class Solution {
public:
    bool isSubstringPresent(string s) {
        unordered_set<string> pairs;
        for (int i = 0; i + 1 < s.size(); ++i) pairs.insert(s.substr(i, 2));
        for (int i = 0; i + 1 < s.size(); ++i) {
            string rev = {s[i + 1], s[i]};
            if (pairs.count(rev)) return true;
        }
        return false;
    }
};

class Solution {
    public boolean isSubstringPresent(String s) {
        Set<String> pairs = new HashSet<>();
        for (int i = 0; i + 1 < s.length(); i++) pairs.add(s.substring(i, i + 2));
        for (int i = 0; i + 1 < s.length(); i++) {
            String rev = "" + s.charAt(i + 1) + s.charAt(i);
            if (pairs.contains(rev)) return true;
        }
        return false;
    }
}

var isSubstringPresent = function(s) {
    const pairs = new Set();
    for (let i = 0; i + 1 < s.length; ++i) pairs.add(s.slice(i, i + 2));
    for (let i = 0; i + 1 < s.length; ++i) {
        const rev = s[i + 1] + s[i];
        if (pairs.has(rev)) return true;
    }
    return false;
};
